88	// 四位年份范围（与输入格式 YYYY 一致）；系列推算出的时间落在此范围外即拒绝
89	const MIN_YEAR = 1;
90	const MAX_YEAR = 9999;
91	// 系列最大次数：首项 + 每周一次，杜绝荒谬输入导致的长循环
92	const MAX_OCCURRENCES = 100000;
