// 四位年份范围（与输入格式 YYYY 一致）；系列推算出的时间落在此范围外即拒绝
const MIN_YEAR = 1;
const MAX_YEAR = 9999;
// 系列最大次数：首项 + 每周一次，杜绝荒谬输入导致的长循环
const MAX_OCCURRENCES = 100000;

// ---------------------------------------------------------------------------
// 错误类型：UsageError -> 退出码 2；BizError -> 退出码 1
