1109	
1110	const LOCK_TIMEOUT_MS = 5000; // 取得写入保护的最长等待时间
1111	const LOCK_RETRY_MS = 40; // 竞争重试间隔（含随机抖动，避免齐步）
1112	
1113	// 数据文件的规范路径：解析相对路径与 ./..，并尽量解析符号链接
1114	// （文件尚不存在时解析其父目录，父目录也不可用时退化为绝对路径）
1115	function canonicalDataPath(file: string): string {
1116	  const abs = resolve(file);
1117	  try {
1118	    return realpathSync(abs);
1119	  } catch {
1120	    try {
1121	      return join(realpathSync(dirname(abs)), basename(abs));
1122	    } catch {
1123	      return abs;
1124	    }
1125	  }
1126	}
1127	
1128	// 锁文件路径：与数据文件同目录、按规范路径命名；文件名长度受限（如 255 字节）
1129	// 时退化为同目录下的散列锁名，同一数据文件的所有进程仍共享同一把锁
1130	function lockPathFor(file: string): string {
1131	  const canonical = canonicalDataPath(file);
1132	  const primary = `${canonical}.lock`;
1133	  if (Buffer.byteLength(basename(primary), 'utf8') <= 250) return primary;
1134	  const hash = createHash('sha256').update(canonical).digest('hex').slice(0, 24);
1135	  return join(dirname(canonical), `.shiftbook-${hash}.lock`);
