1139	// 按规范路径命名并受文件名长度限制（超限时同样退化为同目录散列名）
1140	function recoveryPathFor(file: string): string {
1141	  const lockPath = lockPathFor(file);
1142	  const primary = `${lockPath}.recover`;
1143	  if (Buffer.byteLength(basename(primary), 'utf8') <= 250) return primary;
1144	  const canonical = canonicalDataPath(file);
1145	  const hash = createHash('sha256').update(`${canonical}recover`).digest('hex').slice(0, 24);
1146	  return join(dirname(canonical), `.shiftbook-${hash}.recover`);
