3053	// 解析并校验需求组：至少一组（由调用方保证），每组非空；
3054	// 组内重复或未知资源拒绝；同一资源允许出现在不同组（求解时保证所选互不相同）
3055	function parseRequirementGroups(store: Store, rawGroups: string[]): RequirementGroup[] {
3056	  return rawGroups.map((raw, i) => {
3057	    const label = `第 ${i + 1} 需求组`;
3058	    const ids = raw.split(',').map((s) => s.trim());
3059	    if (ids.some((s) => s === '')) {
3060	      throw new BizError(
3061	        `${label}为空或含空项: “${raw}”，应为逗号分隔的已登记资源标识（如 R0001,R0002）`,
3062	      );
3063	    }
3064	    const seen = new Set<string>();
3065	    const dupes: string[] = [];
3066	    for (const id of ids) {
3067	      if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3068	      seen.add(id);
3069	    }
3070	    if (dupes.length > 0) throw new BizError(`${label}内候选资源重复: ${dupes.join('、')}`);
3071	    const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3072	    if (unknown.length > 0) throw new BizError(`${label}含未知资源标识: ${unknown.join('、')}`);
3073	    return {index: i + 1, candidates: [...seen].sort()};
3074	  });
3075	}
