3080	// excludeBookingIds 中的预约（弹性批量改期、停用同次改期的本批预约）旧占用不计；
3081	// extraCuts 为拟登记但尚未落盘的停用区间（add-closure 附改期清单时计入）
3082	function resourceFreeSegments(
3083	  store: Store,
3084	  id: string,
3085	  wStart: number,
3086	  wEnd: number,
3087	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
3088	  extraCuts: ReadonlyArray<[number, number]> = [],
3089	): Array<[number, number]> {
3090	  const r = store.resources.find((x) => x.id === id)!;
3091	  const available = clipSegments(availableSegmentsOf(store, r, extraCuts), wStart, wEnd);
3092	  const busy: Array<[number, number]> = [];
3093	  for (const b of store.bookings) {
3094	    if (b.status !== 'active') continue;
3095	    if (excludeBookingIds.has(b.id)) continue;
3096	    if (!b.resourceIds.includes(id)) continue;
3097	    const bStart = parseDateTime(b.start, '预约开始时间');
3098	    const bEnd = parseDateTime(b.end, '预约结束时间');
3099	    const a = Math.max(bStart, wStart);
3100	    const c = Math.min(bEnd, wEnd);
3101	    if (a < c) busy.push([a, c]);
3102	  }
3103	  return subtractSegments(available, busy);
3104	}
