3572	function* assignmentsInLexOrder(
3573	  groups: RequirementGroup[],
3574	  usable: (id: string) => boolean,
3575	): Generator<string[], void, undefined> {
3576	  const used = new Set<string>();
3577	  const acc: string[] = [];
3578	  function* rec(g: number): Generator<string[], void, undefined> {
3579	    if (g === groups.length) {
3580	      yield [...acc];
3581	      return;
3582	    }
3583	    for (const id of groups[g].candidates) {
3584	      if (used.has(id) || !usable(id)) continue;
3585	      used.add(id);
3586	      acc.push(id);
3587	      yield* rec(g + 1);
3588	      acc.pop();
3589	      used.delete(id);
3590	    }
3591	  }
3592	  yield* rec(0);
3593	}
