3603	    const m = new Map<string, Array<[number, number]>>();
3604	    for (const g of it.groups) {
3605	      for (const id of g.candidates) {
3606	        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin));
3607	      }
3608	    }
3609	    return m;
3610	  });
3611	
3612	  // 候选开始分钟闭包：
3613	  // 1) 基础空闲段起点；
3614	  // 2) “被其他项占用结束顶住”的起点 s_i = s_j + d_j（仅候选资源集合有交集的项
3615	  //    之间传播，对应共同资源左闭右开冲突的边界）；
3616	  // 3) 项间关系边界：关系 p -> q（间隔 [lo,hi]）要求 s_p + d_p + lo <= s_q
3617	  //    <= s_p + d_p + hi。已知 s_p 时 s_q 的边界为 s_p+d_p+lo、s_p+d_p+hi；
3618	  //    已知 s_q 时 s_p 的边界为 s_q-d_p-hi、s_q-d_p-lo（关系可逆清单顺序、
3619	  //    也适用于不同资源的项）。
3620	  // 最小方案中每项的开始必落在自身窗口内某约束边界的闭包上（按开始分钟归纳：
3621	  // 若两侧均不贴边界即可整体平移至更小开始，与最小性矛盾），闭包在有限整数
3622	  // 值域（各项窗内）上迭代必收敛。
3623	  const candidateIds = items.map((it) => {
3624	    const set = new Set<string>();
3625	    for (const g of it.groups) for (const id of g.candidates) set.add(id);
3626	    return set;
3627	  });
3628	  const sharesCandidate = (a: number, b: number): boolean => {
