3636	    for (const rel of it.incoming) outgoing[rel.predecessor - 1].push(rel);
3637	  });
3638	  const relBetween = new Map<string, FlexRelation[]>(); // “a,b”（a<b 的下标）上的关系（含各自方向）
3639	  items.forEach((it) => {
3640	    for (const rel of it.incoming) {
3641	      const a = Math.min(rel.predecessor, rel.successor) - 1;
3642	      const b = Math.max(rel.predecessor, rel.successor) - 1;
3643	      const key = `${a},${b}`;
3644	      const list = relBetween.get(key) ?? [];
3645	      list.push(rel);
3646	      relBetween.set(key, list);
