3655	        if (fitsWindow(i, s)) set.add(s);
3656	      }
3657	    }
3658	    return set;
3659	  });
3660	  let changed = true;
3661	  while (changed) {
3662	    changed = false;
3663	    const add = (i: number, t: number): void => {
3664	      if (fitsWindow(i, t) && !candStarts[i].has(t)) {
3665	        candStarts[i].add(t);
3666	        changed = true;
3667	      }
3668	    };
