3677	          const b = Math.max(i, j);
3678	          for (const rel of relBetween.get(`${a},${b}`) ?? []) {
3679	            if (rel.predecessor - 1 === j && rel.successor - 1 === i) {
3680	              // j 是前项、i 是后项：s_i = s_j + d_j + [min,max]
