3695	  const placedStart = new Array<number | null>(n).fill(null);
3696	  const placedEnd = new Array<number | null>(n).fill(null);
3697	  const occById = new Map<string, Array<[number, number]>>();
3698	
3699	  // 放置 idx（[s,e]）时，对全部两端都已放置的关系做边界检查（含两端）；
3700	  // 每条边恰在其第二个端点放置时被检查一次
3701	  const relationsSatisfied = (idx: number, s: number, e: number): boolean => {
3702	    for (const rel of items[idx].incoming) {
3703	      // idx 是后项；前项可能尚未放置（逆清单顺序），稍后在前项放置处检查
3704	      const predEnd = placedEnd[rel.predecessor - 1];
3705	      if (predEnd !== null && (s - predEnd < rel.minGap || s - predEnd > rel.maxGap)) return false;
3706	    }
3707	    for (const rel of outgoing[idx]) {
3708	      // idx 是前项；后项可能先放置（逆清单顺序）
3709	      const succStart = placedStart[rel.successor - 1];
3710	      if (succStart !== null && (succStart - e < rel.minGap || succStart - e > rel.maxGap)) return false;
3711	    }
3712	    return true;
3713	  };
3714	
3715	  const search = (idx: number): FlexPlacement[] | null => {
3716	    if (idx === n) return [];
3717	    const it = items[idx];
3718	    // 当前空闲段 = 基础空闲段扣除已放置项占用
3719	    const freeById = new Map<string, Array<[number, number]>>();
3720	    for (const [id, segs] of baseFree[idx]) {
3721	      const occ = occById.get(id);
3722	      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
3723	    }
3724	    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
