3896	      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的候选资源组）`);
3897	    } else {
3898	      rec.groups.forEach((g, gi) => {
3899	        if (!Array.isArray(g) || g.length === 0) {
3900	          problems.push(`${at} 第 ${gi + 1} 候选资源组必须是非空数组（可任选其一的候选资源标识）`);
