4292	function peakConcurrency(
4293	  occupiedSets: Array<Array<[number, number]>>,
4294	): {peak: number; intervals: Array<[number, number]>} {
4295	  const delta = new Map<number, number>();
4296	  for (const segs of occupiedSets) {
