4298	      delta.set(s, (delta.get(s) ?? 0) + 1);
4299	      delta.set(e, (delta.get(e) ?? 0) - 1);
4300	    }
4301	  }
4302	  const times = [...delta.keys()].sort((a, b) => a - b);
4303	  let count = 0;
4304	  let peak = 0;
4305	  const intervals: Array<[number, number]> = [];
4306	  for (let i = 0; i < times.length; i++) {
4307	    count += delta.get(times[i])!;
4308	    const next = times[i + 1];
4309	    if (next === undefined || next === times[i]) continue;
4310	    if (count > peak) {
4311	      peak = count;
4312	      intervals.length = 0; // 更高的峰值出现：此前累计的旧峰值区间作废
4313	      intervals.push([times[i], next]);
4314	    } else if (count === peak && peak > 0) {
