5524	// TEXT 值转义：反斜杠、逗号、分号与换行（\r\n、\r、\n 统一转义为 \n）。
5525	// 必须先转义反斜杠，避免对后续加入的转义符二次转义。
5526	function escapeIcalText(value: string): string {
5527	  return value
5528	    .replace(/\\/g, '\\\\')
