5543	// 合法 UTC 时间戳 YYYYMMDDTHHMMSSZ（DTSTAMP）
5544	function icalUtcStamp(d: Date): string {
5545	  const p = (n: number): string => String(n).padStart(2, '0');
5546	  return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
5547	    `T${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}Z`;
5548	}
