5550	// RFC 5545 折行：物理行（不计 CRLF，但计续行前导空格）不超过 75 个 UTF-8 字节，
5551	// 续行以一个空格开头（故续行内容至多 74 字节）；按 Unicode 码点切分，绝不拆开
5552	// 一个字符（含增补平面的 4 字节字符）。每条逻辑行以 CRLF 结束。
5553	function foldIcalLine(line: string): string {
5554	  const pieces: string[] = [];
5555	  let cur = '';
5556	  let curBytes = 0;
5557	  let limit = 75; // 首行 75；续行需扣除一个前导空格
5558	  for (const ch of line) {
5559	    const n = Buffer.byteLength(ch, 'utf8'); // for...of 按码点迭代，代理对成对出现
5560	    if (curBytes + n > limit) {
5561	      pieces.push(cur);
5562	      cur = '';
5563	      curBytes = 0;
5564	      limit = 74;
5565	    }
5566	    cur += ch;
5567	    curBytes += n;
5568	  }
5569	  pieces.push(cur);
5570	  const physical = [pieces[0], ...pieces.slice(1).map((x) => ' ' + x)];
5571	  return physical.join('\r\n') + '\r\n';
5572	}
