5637	    // 比较基线永远是“原周展开”：首项时间按 7 个营业地日历日纯算术后移，
5638	    // 资源集合取首次导入集合；首次导入的例外快照不参与比较。
5639	    const origStartMin = masterStartMin + k * weekMinutes;
5640	    const origEndMin = masterEndMin + k * weekMinutes;
5641	    const curStartMin = parseDateTime(b.start, `成员 ${b.id} 当前开始时间`);
5642	    const curEndMin = parseDateTime(b.end, `成员 ${b.id} 当前结束时间`);
5643	    const baseResources = rec.resourceIds; // 加载时已按标识排序
5644	    const curResources = b.resourceIds; // 加载时已按标识排序
5645	    const sameTime = curStartMin === origStartMin && curEndMin === origEndMin;
5646	    const sameResources =
5647	      baseResources.length === curResources.length && baseResources.every((id, j) => id === curResources[j]);
