5662	  lines.push('BEGIN:VEVENT');
5663	  lines.push(`UID:${escapeIcalText(rec.uid)}`);
5664	  lines.push(`DTSTAMP:${stamp}`);
5665	  lines.push(`DTSTART:${floatingToIcal(rec.start, '导入快照首项开始时间')}`);
5666	  lines.push(`DTEND:${floatingToIcal(rec.end, '导入快照首项结束时间')}`);
5667	  lines.push(`RRULE:FREQ=WEEKLY;COUNT=${rec.count}`);
5668	  if (excludedSorted.length > 0) {
5669	    lines.push(`EXDATE:${excludedSorted.map((t) => floatingToIcal(t, '排除时间')).join(',')}`);
5670	  }
5671	  lines.push(`DESCRIPTION:${escapeIcalText(resourceDescription(store, rec.resourceIds))}`);
5672	  lines.push('END:VEVENT');
5673	  // 例外随主事件之后，按原发生顺序排列
5674	  for (const ex of exceptions) {
5675	    lines.push('BEGIN:VEVENT');
5676	    lines.push(`UID:${escapeIcalText(rec.uid)}`);
5677	    lines.push(`RECURRENCE-ID:${floatingToIcal(ex.recurrenceId, '原发生时间')}`);
5678	    lines.push(`DTSTAMP:${stamp}`);
5679	    lines.push(`DTSTART:${floatingToIcal(ex.start, '成员当前开始时间')}`);
5680	    lines.push(`DTEND:${floatingToIcal(ex.end, '成员当前结束时间')}`);
5681	    lines.push(`DESCRIPTION:${escapeIcalText(resourceDescription(store, ex.resourceIds))}`);
5682	    lines.push('END:VEVENT');
5683	  }
5684	  lines.push('END:VCALENDAR');
5685	
5686	  return {
5687	    content: lines.map(foldIcalLine).join(''),
5688	    activeCount,
5689	    exclusionCount: excludedSorted.length,
5690	    exceptionCount: exceptions.length,
