// 单个资源在“活动时间坐标”下、活动窗口 [wStart, wEnd) 内可供活动使用的连续区间。
// 窗口只限制活动起止；准备/整理可伸出窗口，但仍须落在实际可用时间内：
//   实际可用段 [a,b)（开放合并扣除有效停用，extraCuts 为拟登记停用）
//     -> 活动可行段 [a+准备, b-整理)（活动 [s,e) 须使 [s-准备,e+整理) 被完整覆盖）；
//   有效预约（活动 [bs,be)）在活动坐标下阻挡 [bs-(准备+整理), be+(准备+整理))
//     （新活动与其仅准备/整理端点相接时不重叠，自然可行；已取消不阻挡）；
// 最后裁进活动窗口。excludeBookingIds 中的预约（弹性改期、停用同次改期的本批预约）
// 旧占用不计。新活动可行性（覆盖+冲突）等价于 [s,e) 被返回区间完整覆盖；
// 可行即意味着实际占用未越出 0001-9999 年（开放段本身在年份域内）。
function resourceActivityFreeSegments(
  store: Store,
  r: ResourceRec,
  wStart: number,
  wEnd: number,
  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
  extraCuts: ReadonlyArray<[number, number]> = [],
): Array<[number, number]> {
  const p = r.prepMinutes;
  const q = r.teardownMinutes;
  const availActivity: Array<[number, number]> = [];
  for (const [a, b] of availableSegmentsOf(store, r, extraCuts)) {
    const s = a + p;
    const e = b - q;
    if (s < e) availActivity.push([s, e]);
  }
  let free = clipSegments(mergeIntervals(availActivity), wStart, wEnd);
  const buf = p + q;
  const busy: Array<[number, number]> = [];
  for (const bk of store.bookings) {
    if (bk.status !== 'active') continue;
    if (excludeBookingIds.has(bk.id)) continue;
    if (!bk.resourceIds.includes(r.id)) continue;
    const bs = parseDateTime(bk.start, '预约开始时间');
    const be = parseDateTime(bk.end, '预约结束时间');
    busy.push([bs - buf, be + buf]);
  }
  if (busy.length > 0) free = subtractSegments(free, mergeIntervals(busy));
  return free;
}

// 窗口内全部资源在活动坐标下的共同实际可行区间（不计预约占用）：
// 各资源 [a+准备,b-整理) 段裁进窗口后逐组求交——登记弹性候补时用（登记忽略占用）
function commonActivityAvailableSegments(
  store: Store,
  ids: string[],
  wStart: number,
  wEnd: number,
): Array<[number, number]> {
  let common: Array<[number, number]> = [[wStart, wEnd]];
  for (const id of ids) {
    const r = store.resources.find((x) => x.id === id)!;
    const segs = resourceActivityFreeSegments(store, r, wStart, wEnd, new Set(store.bookings.map((b) => b.id)));
    common = intersectSegments(common, segs);
    if (common.length === 0) break;
  }
  return common;
}

