1	// shiftbook add-closure 附本地弹性改期清单（停用与替代安排一次原子提交）回归测试
2	//
3	// 运行：npm test（本文件随全部测试一起执行）
4	// 说明：
5	// - 使用 Node.js 24 内置测试运行器（node:test），无外部依赖、不访问网络；
6	// - 全部经命令行入口（node app.ts --data <临时文件>）操作，不读取用户默认数据文件；
7	// - 每个场景使用独立临时数据目录，保存结果由新进程查询（list-bookings、
8	//   list-closures、list-batch-ops、list-series、list-waitlist、import-ical 重放）；
9	// - 覆盖：不附清单原行为（重叠拒绝/端点相接成功）、换资源才能成立、同开始先比
10	//   开始分钟再按组序字典序、候选与清单书写顺序不影响结果、腾挪链（额外纳入他项
11	//   才成立）、漏项一次性列全并拒绝、整单无解、撤销受阻（停用仍有效时整笔拒绝、
12	//   取消停用后整笔恢复、期间被改则一致性拒绝）、混合身份（系列/导入/候补兑现，
13	//   归属与关联保留）、无变化只推进停用计数、取消停用不自动恢复预约、非法清单与
14	//   用法错误退出码、真实保存失败与重试（停用与操作标识均未消费）、锁竞争退出 1；
15	// - 任一断言失败即非零退出，输出中标注场景与步骤；结束后自动清理临时文件。
16	
17	import {test} from 'node:test';
18	import assert from 'node:assert/strict';
19	import {spawnSync, spawn, type ChildProcess} from 'node:child_process';
20	import {mkdtempSync, mkdirSync, rmSync, writeFileSync, readFileSync, existsSync} from 'node:fs';
21	import {tmpdir} from 'node:os';
22	import {join, dirname} from 'node:path';
23	import {fileURLToPath} from 'node:url';
24	
25	const APP = join(dirname(fileURLToPath(import.meta.url)), '..', 'app.ts');
26	const OPEN_ALL: Array<[string, string]> = [['2026-01-01T00:00', '2027-01-01T00:00']];
27	// 255 字节文件名：保存时临时文件（<名>.<pid>.tmp）必然超出文件名长度上限，
28	// 可重复触发真实保存失败。
29	const LONG_NAME = 'c'.repeat(250) + '.json';
30	
31	interface CliResult {
32	  status: number;
33	  stdout: string;
34	  stderr: string;
35	}
36	
37	function runCli(dataFile: string, args: string[]): CliResult {
38	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
39	  if (r.error) throw r.error;
40	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
41	}
42	
43	function ok(df: string, args: string[], ctx: string): CliResult {
44	  const r = runCli(df, args);
45	  assert.equal(
46	    r.status,
47	    0,
48	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
49	  );
50	  return r;
51	}
52	
53	function bizFail(df: string, args: string[], ctx: string): CliResult {
54	  const r = runCli(df, args);
55	  assert.equal(
56	    r.status,
57	    1,
58	    `[${ctx}] 期望退出 1，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
59	  );
60	  return r;
61	}
62	
63	function usageFail(df: string, args: string[], ctx: string): CliResult {
64	  const r = runCli(df, args);
65	  assert.equal(
66	    r.status,
67	    2,
68	    `[${ctx}] 期望退出 2，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
69	  );
70	  return r;
71	}
72	
73	function tempDir(t: {after: (fn: () => void) => void}): string {
74	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-add-closure-flex-test-'));
75	  t.after(() => rmSync(dir, {recursive: true, force: true}));
76	  return dir;
77	}
78	
79	function addResource(
80	  df: string,
81	  name: string,
82	  open: Array<[string, string]> = OPEN_ALL,
83	  type = 'venue',
84	): void {
85	  const args = ['add-resource', '--type', type, '--name', name];
86	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
87	  ok(df, args, `登记资源 ${name}`);
88	}
89	
90	function addBooking(df: string, resources: string[], start: string, end: string, ctx: string): void {
91	  const args = ['create-booking'];
92	  for (const r of resources) args.push('--resource', r);
93	  args.push('--start', start, '--end', end);
94	  ok(df, args, ctx);
95	}
96	
97	interface FlexItem {
98	  bookingId: string;
99	  window: string;
100	  groups: string[][];
101	}
102	
103	function writeManifest(dir: string, name: string, items: FlexItem[]): string {
104	  const p = join(dir, name);
105	  writeFileSync(p, JSON.stringify({items}) + '\n', 'utf8');
106	  return p;
107	}
108	
109	function writeRawManifest(dir: string, name: string, raw: string): string {
110	  const p = join(dir, name);
111	  writeFileSync(p, raw, 'utf8');
112	  return p;
113	}
114	
115	function closureWith(
116	  df: string,
117	  resource: string,
118	  start: string,
119	  end: string,
120	  manifest: string,
121	  ctx: string,
122	): CliResult {
123	  return ok(df, ['add-closure', '--resource', resource, '--start', start, '--end', end, manifest], ctx);
124	}
125	
126	function readStore(df: string): any {
127	  return JSON.parse(readFileSync(df, 'utf8'));
128	}
129	
130	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
131	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 失败不得改动数据文件（逐字节比对）`);
132	}
133	
134	function assertBooking(
135	  df: string,
136	  id: string,
137	  start: string,
138	  end: string,
139	  resourceIds: string[],
140	  ctx: string,
141	): void {
142	  const store = readStore(df);
143	  const b = (store.bookings as any[]).find((x) => x.id === id);
144	  assert.ok(b, `[${ctx}] 应存在预约 ${id}`);
145	  assert.equal(b.start, start, `[${ctx}] ${id} 开始时间`);
146	  assert.equal(b.end, end, `[${ctx}] ${id} 结束时间`);
147	  assert.deepEqual(b.resourceIds, [...resourceIds].sort(), `[${ctx}] ${id} 资源集合`);
148	  assert.equal(b.status, 'active', `[${ctx}] ${id} 状态`);
149	}
150	
151	interface ExpectedMove {
152	  id: string;
153	  start: string;
154	  end: string;
155	  picks: string[];
156	}
157	
158	// 断言 add-closure 附清单成功输出：停用标识、可选操作标识、各项时间与按组资源
159	function assertClosureMove(
160	  r: CliResult,
161	  closureId: string,
162	  opId: string | null,
163	  expected: ExpectedMove[],
164	  ctx: string,
165	): void {
